def list_page(items, cursor, size):
    if size < 1:
        raise ValueError("size must be at least 1")

    if not items:
        return [], None

    # Sort: score descending, then id ascending
    # Key: (-score, id)
    sorted_items = sorted(items, key=lambda x: (-x['score'], x['id']))

    if cursor is None:
        start_idx = 0
    else:
        try:
            decoded = base64.b64decode(cursor).decode('utf-8')
            score_str, id_str = decoded.split('|')
            score = float(score_str)

            start_idx = -1
            for i, item in enumerate(sorted_items):
                if (-item['score'], item['id']) > (-score, id_str):
                    start_idx = i
                    break

            if start_idx == -1:
                start_idx = len(sorted_items)
        except Exception:
            # Any decode error, split error, or float conversion error
            raise ValueError("Malformed cursor")

    page = sorted_items[start_idx : start_idx + size]

    if not page:
        return [], None

    # If we've reached the end of the list
    if start_idx + len(page) == len(sorted_items):
        return page, None

    # Otherwise, the next cursor is the last item of the current page
    last_item = page[-1]
    cursor_val = f"{last_item['score']}|{last_item['id']}"
    nxt = base64.b64encode(cursor_val.encode('utf-8')).decode('utf-8')

    return page, nxt
